package com.example;

import com.influxdb.v3.client.InfluxDBClient;
import com.influxdb.v3.client.Point;
import com.influxdb.v3.client.query.QueryOptions;
import com.influxdb.v3.client.query.QueryType;
import io.github.cdimascio.dotenv.Dotenv;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Arrays;
import java.util.Map;
import java.util.stream.Stream;

public final class InfluxService {

    public static void main(String[] args) throws Exception {
        Dotenv env = Dotenv.configure().ignoreIfMissing().load(); // falls back to real env vars
        String host = require(env, "INFLUXDB_HOST");
        String token = require(env, "INFLUXDB_TOKEN");
        String database = require(env, "INFLUXDB_DATABASE");

        checkServer(host, token);

        try (InfluxDBClient client = InfluxDBClient.getInstance(host, token.toCharArray(), database)) {
            checkDatabaseExists(client, database);

            // Smoke test: write one point with an explicit timestamp, then read it back.
            Point p = Point.measurement("service_heartbeat")
                    .setTag("service", "my-java-service")
                    .setIntegerField("up", 1L)
                    .setTimestamp(Instant.now().truncatedTo(ChronoUnit.SECONDS));
            client.writePoint(p);

            QueryOptions opts = new QueryOptions().withQueryType(QueryType.SQL)
                    .withParameters(Map.of("service", "my-java-service"));
            try (Stream<Object[]> rows = client.query(
                    "SELECT * FROM service_heartbeat WHERE service = $service ORDER BY time DESC LIMIT 5", opts)) {
                rows.forEach(r -> System.out.println(Arrays.toString(r)));
            }
        }
    }

    /** GET /ping: confirms the server is reachable, the token is accepted, and it's Enterprise. */
    private static void checkServer(String host, String token) throws Exception {
        HttpClient http = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();
        HttpRequest req = HttpRequest.newBuilder(URI.create(host.replaceAll("/+$", "") + "/ping"))
                .header("Authorization", "Bearer " + token)
                .timeout(Duration.ofSeconds(5))
                .GET().build();
        HttpResponse<Void> resp = http.send(req, HttpResponse.BodyHandlers.discarding());
        if (resp.statusCode() == 401) {
            throw new IllegalStateException("Server is up at " + host + " but rejected INFLUXDB_TOKEN (401).");
        }
        if (resp.statusCode() != 200) {
            throw new IllegalStateException("Unexpected /ping status " + resp.statusCode() + " from " + host);
        }
        String build = resp.headers().firstValue("x-influxdb-build").orElse("");
        if (!build.toLowerCase().contains("enterprise")) {
            System.err.println("Warning: expected InfluxDB 3 Enterprise, server reports build '" + build + "'");
        }
    }

    /**
     * InfluxDB 3 silently auto-creates a database on first write, so a typo in INFLUXDB_DATABASE
     * would "succeed" and send data to the wrong place. Fail fast instead.
     * A database-scoped token can't list databases, so probe the target DB with a cheap query.
     */
    private static void checkDatabaseExists(InfluxDBClient client, String database) {
        try (Stream<Object[]> rows = client.query(
                "SELECT table_name FROM information_schema.tables LIMIT 1")) {
            rows.count();
        } catch (RuntimeException e) {
            throw new IllegalStateException("Database '" + database + "' is missing or not readable with "
                    + "INFLUXDB_TOKEN. Create it with: influxdb3 create database " + database
                    + " --token \"$INFLUXDB_ADMIN_TOKEN\"", e);
        }
    }

    private static String require(Dotenv env, String key) {
        String v = env.get(key);
        if (v == null || v.isBlank()) throw new IllegalStateException("Missing env var " + key);
        return v;
    }
}
```

## Things to know

- **Why the startup check:** a write to a misspelled database (say `senor_data`) reports success and quietly creates a new, wrong database. The check stops the service with a clear error instead. You can remove it if your deployment pipeline creates the database explicitly.
- **The database check is my own design, not tested.** The skill's examples use the admin token to list databases. A scoped token can't do that, so the code runs a small query against the target database instead. I expect that query to fail when the database doesn't exist, but haven't confirmed it against a server.
- **Share one client for the whole service.** `InfluxDBClient` is meant to be created once and reused, then closed at shutdown, not opened per request.
- **Writes:** the client writes through `/api/v2/write` by default, where one bad line rejects the whole batch. To get partial writes or `noSync`, set the `useV2Api` write option to `false`. For volume, batch with `writePoints(List<Point>)`, up to 10,000 lines or 10 MB per request. Retry 5xx and 429 errors with backoff; surface 4xx errors.
- **Untrusted input:** strip or reject `\n` and `\r` in tag and field values. In queries, always use `$param` parameters, as above, never string concatenation.

