```java
package com.example;

import com.influxdb.v3.client.InfluxDBClient;
import com.influxdb.v3.client.Point;
import com.influxdb.v3.client.query.QueryOptions;
import com.influxdb.v3.client.query.QueryType;
import io.github.cdimascio.dotenv.Dotenv;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.regex.Pattern;
import java.util.stream.Stream;

public class InfluxService {

    public static void main(String[] args) throws Exception {
        Dotenv env = Dotenv.configure().ignoreIfMissing().load();   // real env vars take precedence
        String host  = require(env, "INFLUXDB_HOST");
        String token = require(env, "INFLUXDB_TOKEN");
        String db    = require(env, "INFLUXDB_DATABASE");

        try (InfluxDBClient client = InfluxDBClient.getInstance(host, token.toCharArray(), db)) {
            verifyDatabaseExists(client, host, token, db);

            // Write: use the event's own timestamp at second precision
            Instant ts = Instant.now().truncatedTo(ChronoUnit.SECONDS);
            List<Point> points = List.of(
                Point.measurement("sensor")
                    .setTag("host", "server01")
                    .setTag("region", "us-west")
                    .setFloatField("temperature", 72.4)
                    .setFloatField("humidity", 45.1)
                    .setTimestamp(ts));
            client.writePoints(points);

            // Query: user input goes in as a parameter, never concatenated into SQL
            QueryOptions opts = new QueryOptions().withQueryType(QueryType.SQL)
                .withParameters(Map.of("host", "server01"));
            try (Stream<Object[]> rows = client.query(
                    "SELECT time, host, temperature, humidity FROM sensor " +
                    "WHERE host = $host AND time > now() - INTERVAL '1 hour' ORDER BY time DESC LIMIT 10",
                    opts)) {
                rows.forEach(r -> System.out.println(Arrays.toString(r)));
            }
        }
    }

    /**
     * InfluxDB 3 creates a database automatically the first time something writes to it.
     * A typo like "senor_data" would "succeed" and quietly send data to a new, wrong database.
     * So stop at startup unless the target database already exists.
     */
    static void verifyDatabaseExists(InfluxDBClient client, String host, String token, String db)
            throws Exception {
        HttpRequest req = HttpRequest.newBuilder(
                URI.create(host.replaceAll("/+$", "") + "/api/v3/configure/database?format=json"))
            .header("Authorization", "Bearer " + token).GET().build();
        HttpResponse<String> resp = HttpClient.newHttpClient()
            .send(req, HttpResponse.BodyHandlers.ofString());

        if (resp.statusCode() == 200) {
            Pattern p = Pattern.compile("\"iox::database\"\\s*:\\s*\"" + Pattern.quote(db) + "\"");
            if (!p.matcher(resp.body()).find()) {
                throw new IllegalStateException("Database '" + db + "' does not exist. Create it with: " +
                    "influxdb3 create database " + db + " --token \"$INFLUXDB_ADMIN_TOKEN\"");
            }
            return;
        }
        if (resp.statusCode() == 401) {
            throw new IllegalStateException("INFLUXDB_TOKEN was rejected (401). Check the token and host.");
        }
        // A scoped token may not be allowed to list databases (403). Fall back to a read on the
        // target database: queries don't auto-create, so a missing database causes an error here.
        try (Stream<Object[]> rows = client.query("SHOW TABLES",
                new QueryOptions().withQueryType(QueryType.SQL))) {
            rows.findFirst();
        } catch (RuntimeException e) {
            throw new IllegalStateException("Cannot read database '" + db +
                "'. It may not exist, or the token lacks read on it: " + e.getMessage(), e);
        }
    }

    static String require(Dotenv env, String key) {
        String v = env.get(key);
        if (v == null || v.isBlank()) throw new IllegalStateException("Missing env var " + key);
        return v;
    }
}
```

## Things to know

- **Create one client and reuse it.** `InfluxDBClient` is thread-safe and holds connections, so share a single instance across the service (for example, as a singleton bean) and close it on shutdown.
- **Batch your writes.** Send up to 10,000 lines or 10 MB per `writePoints` call. For a live stream, also flush on a timer, about once a second.
- **Which errors to retry:** retry 5xx, 429 and timeouts, with backoff and jitter. Treat 400, 401, 403, 404 and 413 as errors to log or raise; retrying won't fix them.
- **Partial writes:** by default the client writes through `/api/v2/write`, where one bad line rejects the whole batch. To have valid lines stored and only bad lines rejected, set the write option `useV2Api` to `false`. That sends writes to `/api/v3/write_lp`, which also supports `noSync`.
- **Untrusted input:** if tag or field values come from users, remove or reject `\n` and `\r` first. A newline in a value can create an extra, forged point.
- **Same timestamp means a merge:** two points with the same table, tags and timestamp are merged, and there's no guarantee which field value is kept. If one series can get more than one point per second, use finer precision than seconds.
- **The database check is optional.** You can remove it, but it's the only thing that catches a typo in `INFLUXDB_DATABASE`. I'm not certain a scoped Enterprise token is allowed to list databases. If it isn't, the code falls back to running `SHOW TABLES` on the database.

