```go
package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"math/rand"
	"net/http"
	"os"
	"time"

	"github.com/InfluxCommunity/influxdb3-go/v2/influxdb3"
	"github.com/influxdata/line-protocol/v2/lineprotocol"
	"github.com/joho/godotenv"
)

func mustEnv(key string) string {
	v := os.Getenv(key)
	if v == "" {
		log.Fatalf("missing required env var %s", key)
	}
	return v
}

// InfluxDB 3 creates a database automatically the first time you write to it.
// A typo like "senor_data" would "succeed" and quietly create a new database,
// so check that the target database exists before writing.
func checkDatabaseExists(ctx context.Context, host, token, db string) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet,
		host+"/api/v3/configure/database?format=json", nil)
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+token)

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return fmt.Errorf("cannot reach InfluxDB at %s: %w", host, err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("listing databases failed: HTTP %d (check INFLUXDB_TOKEN)", resp.StatusCode)
	}

	var dbs []map[string]string
	if err := json.NewDecoder(resp.Body).Decode(&dbs); err != nil {
		return fmt.Errorf("decoding database list: %w", err)
	}
	for _, d := range dbs {
		if d["iox::database"] == db {
			return nil
		}
	}
	return fmt.Errorf("database %q does not exist; create it with: "+
		"influxdb3 create database %s --token \"$INFLUXDB_ADMIN_TOKEN\"", db, db)
}

func main() {
	_ = godotenv.Load()

	host := mustEnv("INFLUXDB_HOST")
	token := mustEnv("INFLUXDB_TOKEN")
	database := mustEnv("INFLUXDB_DATABASE")

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	if err := checkDatabaseExists(ctx, host, token, database); err != nil {
		log.Fatal(err)
	}

	client, err := influxdb3.New(influxdb3.ClientConfig{
		Host:     host,
		Token:    token,
		Database: database,
	})
	if err != nil {
		log.Fatalf("creating client: %v", err)
	}
	defer client.Close()

	// Sample data: 3 sensors, one reading per minute for the last 10 minutes.
	// Each point carries its own timestamp, so a retried write merges into
	// the existing point instead of adding a duplicate.
	sensors := []struct{ id, location string }{
		{"sensor-001", "warehouse"},
		{"sensor-002", "office"},
		{"sensor-003", "server_room"},
	}

	now := time.Now().Truncate(time.Minute)
	var points []*influxdb3.Point
	for _, s := range sensors {
		for i := 10; i > 0; i-- {
			ts := now.Add(-time.Duration(i) * time.Minute)
			p := influxdb3.NewPointWithMeasurement("sensor_reading").
				SetTag("sensor_id", s.id).
				SetTag("location", s.location).
				SetField("temperature", 20+rand.Float64()*5).
				SetField("humidity", 40+rand.Float64()*15).
				SetField("battery_pct", int64(80+rand.Intn(20))).
				SetTimestamp(ts)
			points = append(points, p)
		}
	}

	err = client.WritePoints(ctx, points, influxdb3.WithPrecision(lineprotocol.Second))
	if err != nil {
		var se *influxdb3.ServerError
		if errors.As(err, &se) {
			log.Fatalf("write rejected by server: %s", se.Message)
		}
		log.Fatalf("write failed: %v", err)
	}

	fmt.Printf("Wrote %d points to %q\n", len(points), database)
}
```

