	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("listing databases failed: HTTP %d (check INFLUXDB_TOKEN)", resp.StatusCode)
	}

	var dbs []map[string]string
	if err := json.NewDecoder(resp.Body).Decode(&dbs); err != nil {
		return fmt.Errorf("decoding database list: %w", err)
	}
	for _, db := range dbs {
		if db["iox::database"] == database {
			return nil
		}
	}
	return fmt.Errorf("database %q does not exist; create it with: "+
		"influxdb3 create database %s --token \"$INFLUXDB_ADMIN_TOKEN\"", database, database)
}

func main() {
	_ = godotenv.Load()
	host := mustEnv("INFLUXDB_HOST")
	token := mustEnv("INFLUXDB_TOKEN")
	database := mustEnv("INFLUXDB_DATABASE")

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	if err := ensureDatabaseExists(ctx, host, token, database); err != nil {
		log.Fatal(err)
	}

	client, err := influxdb3.New(influxdb3.ClientConfig{
		Host:     host,
		Token:    token,
		Database: database,
	})
	if err != nil {
		log.Fatalf("creating client: %v", err)
	}
	defer client.Close()

	// Sample data: 3 sensors in different rooms, one reading per minute
	// for the last 10 minutes. Sensor ID and room are tags (they identify
	// the source); the measurements are fields.
	sensors := []struct{ id, room string }{
		{"sensor-001", "kitchen"},
		{"sensor-002", "living_room"},
		{"sensor-003", "garage"},
	}
	now := time.Now().Truncate(time.Second)
	points := make([]*influxdb3.Point, 0, len(sensors)*10)
	for _, s := range sensors {
		for i := 0; i < 10; i++ {
			ts := now.Add(-time.Duration(10-i) * time.Minute)
			points = append(points,
				influxdb3.NewPointWithMeasurement("sensor_reading").
					SetTag("sensor_id", s.id).
					SetTag("room", s.room).
					SetField("temperature", 20.0+rand.Float64()*5).
					SetField("humidity", 40.0+rand.Float64()*15).
					SetField("battery_pct", int64(100-i)).
					SetTimestamp(ts),
			)
		}
	}

	fmt.Printf("==> Writing %d points to %s on %s\n", len(points), database, host)
	if err := client.WritePoints(ctx, points,
		influxdb3.WithPrecision(lineprotocol.Second)); err != nil {
		log.Fatalf("write failed: %v", err)
	}

	fmt.Println("==> Querying the latest 10 rows")
	iter, err := client.Query(ctx,
		"SELECT time, sensor_id, room, temperature, humidity, battery_pct "+
			"FROM sensor_reading ORDER BY time DESC LIMIT 10")
	if err != nil {
		log.Fatalf("query failed: %v", err)
	}
	for iter.Next() {
		fmt.Println(iter.Value())
	}
	if err := iter.Err(); err != nil {
		log.Fatalf("reading query results: %v", err)
	}

	fmt.Println("==> Done")
}
