## `main.go`

```go
package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"math/rand"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/InfluxCommunity/influxdb3-go/v2/influxdb3"
	"github.com/influxdata/line-protocol/v2/lineprotocol"
	"github.com/joho/godotenv"
)

func mustEnv(key string) string {
	v := os.Getenv(key)
	if v == "" {
		log.Fatalf("missing required env var %s (set it in .env or your shell)", key)
	}
	return v
}

// ensureDatabaseExists stops the program if the target database is missing,
// instead of letting the write silently auto-create a misnamed one.
func ensureDatabaseExists(ctx context.Context, host, token, db string) error {
	url := strings.TrimRight(host, "/") + "/api/v3/configure/database?format=json"
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+token)

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return fmt.Errorf("cannot reach InfluxDB at %s: %w", host, err)
	}
	defer resp.Body.Close()

	switch resp.StatusCode {
	case http.StatusOK:
	case http.StatusUnauthorized, http.StatusForbidden:
		return fmt.Errorf("token rejected (HTTP %d): check INFLUXDB_TOKEN", resp.StatusCode)
	default:
		return fmt.Errorf("listing databases failed: HTTP %d", resp.StatusCode)
	}

	var rows []map[string]string
	if err := json.NewDecoder(resp.Body).Decode(&rows); err != nil {
		return fmt.Errorf("decoding database list: %w", err)
	}
	names := make([]string, 0, len(rows))
	for _, r := range rows {
		name := r["iox::database"]
		if name == db {
			return nil
		}
		names = append(names, name)
	}
	return fmt.Errorf("database %q does not exist (found: %v). Create it with:\n  influxdb3 create database %s --token \"$INFLUXDB_ADMIN_TOKEN\"",
		db, names, db)
}

func main() {
	_ = godotenv.Load()

	host := mustEnv("INFLUXDB_HOST")
	token := mustEnv("INFLUXDB_TOKEN")
	database := mustEnv("INFLUXDB_DATABASE")

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	if err := ensureDatabaseExists(ctx, host, token, database); err != nil {
		log.Fatal(err)
	}

	client, err := influxdb3.New(influxdb3.ClientConfig{
		Host:     host,
		Token:    token,
		Database: database,
	})
	if err != nil {
		log.Fatalf("creating client: %v", err)
	}
	defer client.Close()

	// Sample data: 3 sensors in 2 rooms, one reading per minute over the last 10 minutes.
	// Each point gets its own timestamp, so retrying a write merges into the
	// same points rather than creating duplicates.
	sensors := []struct{ id, room string }{
		{"sensor-001", "kitchen"},
		{"sensor-002", "living_room"},
		{"sensor-003", "kitchen"},
	}
	now := time.Now().UTC().Truncate(time.Second)

	var points []*influxdb3.Point
	for _, s := range sensors {
		for i := 10; i > 0; i-- {
			points = append(points,
				influxdb3.NewPointWithMeasurement("home_sensor").
					SetTag("sensor_id", s.id).
					SetTag("room", s.room).
					SetField("temperature", 20.0+rand.Float64()*5).
					SetField("humidity", 35.0+rand.Float64()*15).
					SetField("co2_ppm", int64(400+rand.Intn(400))).
					SetTimestamp(now.Add(-time.Duration(i)*time.Minute)),
			)
		}
	}

	// Second precision: one point per sensor per second is plenty here.
	err = client.WritePoints(ctx, points, influxdb3.WithPrecision(lineprotocol.Second))
	if err != nil {
		var se *influxdb3.ServerError
		if errors.As(err, &se) {
			log.Fatalf("write failed: HTTP %d: %s", se.StatusCode, se.Message)
		}
		log.Fatalf("write failed: %v", err)
	}
	fmt.Printf("Wrote %d points to %q\n", len(points), database)

	// Read back a few rows to confirm the write.
	iter, err := client.Query(ctx,
		"SELECT time, sensor_id, room, temperature, humidity, co2_ppm "+
			"FROM home_sensor WHERE time >= now() - INTERVAL '15 minutes' "+
			"ORDER BY time DESC LIMIT 5")
	if err != nil {
		log.Fatalf("query failed: %v", err)
	}
	for iter.Next() {
		fmt.Println(iter.Value())
	}
	if err := iter.Err(); err != nil {
		log.Fatalf("reading query results: %v", err)
	}
}
