```javascript
// export.mjs
import 'dotenv/config';
import { InfluxDBClient } from '@influxdata/influxdb3-client';

const { INFLUXDB_HOST, INFLUXDB_TOKEN, INFLUXDB_DATABASE } = process.env;
for (const [k, v] of Object.entries({ INFLUXDB_HOST, INFLUXDB_TOKEN, INFLUXDB_DATABASE })) {
  if (!v) throw new Error(`Missing env var ${k}`);
}

// Check the database exists, so a typo fails clearly instead of returning nothing
async function assertDatabaseExists(name) {
  const res = await fetch(`${INFLUXDB_HOST}/api/v3/configure/database?format=json`, {
    headers: { Authorization: `Bearer ${INFLUXDB_TOKEN}` },
  });
  if (!res.ok) throw new Error(`Database check failed: HTTP ${res.status}`);
  const dbs = (await res.json()).map((d) => d['iox::database']);
  if (!dbs.includes(name)) {
    throw new Error(`Database "${name}" not found. Existing: ${dbs.join(', ')}`);
  }
}

const client = new InfluxDBClient({
  host: INFLUXDB_HOST,
  token: INFLUXDB_TOKEN,
  database: INFLUXDB_DATABASE,
});

/**
 * Yields every row in [start, end), one time window at a time.
 * Windows are [a, b), so no row is returned twice or missed at a boundary.
 */
async function* pageByTime(table, start, end, windowMs = 60 * 60 * 1000) {
  // Table names can't be query parameters, so check the name against an allow-list pattern
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(table)) throw new Error('Bad table name');

  const sql = `
    SELECT * FROM "${table}"
    WHERE time >= $start AND time < $end
    ORDER BY time`;

  for (let t = start.getTime(); t < end.getTime(); t += windowMs) {
    const winStart = new Date(t);
    const winEnd = new Date(Math.min(t + windowMs, end.getTime()));
    const params = { start: winStart.toISOString(), end: winEnd.toISOString() };

    let attempt = 0;
    while (true) {
      let yielded = 0;
      try {
        for await (const row of client.query(sql, INFLUXDB_DATABASE, { type: 'sql', params })) {
          yielded++;
          yield row;
        }
        break; // window done
      } catch (err) {
        // A stream can fail partway through. If rows already went out, stop rather than send duplicates.
        const status = err.statusCode;
        const retryable = yielded === 0 && (status === undefined || status === 429 || status >= 500);
        if (!retryable || ++attempt > 5) {
          throw new Error(
            `Window ${params.start}..${params.end} failed after ${yielded} rows: ${err.message}`,
            { cause: err },
          );
        }
        const delay = Math.min(30_000, 500 * 2 ** attempt) * (0.5 + Math.random());
        await new Promise((r) => setTimeout(r, delay));
      }
    }
  }
}

try {
  await assertDatabaseExists(INFLUXDB_DATABASE);

  let n = 0;
  for await (const row of pageByTime(
    'sensor',
    new Date('2026-10-01T00:00:00Z'),
    new Date('2026-11-01T00:00:00Z'),
    15 * 60 * 1000, // 15-minute windows
  )) {
    // process(row) here: write to a file, send downstream, etc.
    if (++n % 100_000 === 0) console.log(`${n} rows`);
  }
  console.log(`Done: ${n} rows`);
} finally {
  await client.close();
}
```

## Notes

- **Choosing the window size:** aim for roughly 50k–500k rows per window. For example, 10M rows spread evenly over 30 days is about 14k rows per hour, so 1–6 hour windows would fit. If your data comes in bursts, use smaller windows. If a query hits a memory limit (status 429), make the window smaller.
- **You can resume:** if the job dies, restart it from the start of the last window that hadn't finished.
- **Only select the columns you need** instead of `SELECT *`. It cuts transfer size a lot at this volume.
- **If you need fixed-size pages** (exactly N rows each), sort on time plus your tag columns and continue from the last row: `WHERE time > $t OR (time = $t AND sensor_id > $id) ORDER BY time, sensor_id LIMIT 10000`. That sort order is unique, because points with the same table, tags, and timestamp merge into one. But you'd have to read the timestamp back from each row, and the windowed version above is simpler.
- **If the export is slow,** InfluxDB's performance tuning is a separate topic: https://docs.influxdata.com/influxdb3/core/admin/performance-tuning/

The approach that holds up at 10 million rows is to page by time window, not by `OFFSET`. With `LIMIT … OFFSET`, every page makes the server re-read and throw away all the rows before it, so page 9,000 costs far more than page 1. Instead, split the time range into fixed half-open windows (`time >= start AND time < end`) and query them one after another.

- **No duplicates or gaps.** Each row falls in exactly one window. This also avoids the problem with "last timestamp seen" cursors, where several sensors share a timestamp and rows get skipped at page edges.
- **Low memory.** The JS client streams results over Arrow Flight as an async iterator, so you handle rows one at a time instead of loading a whole page.

