for (const [k, v] of Object.entries({ INFLUXDB_HOST, INFLUXDB_TOKEN, INFLUXDB_DATABASE })) {
  if (!v) { console.error(`Missing env var ${k}`); process.exit(1); }
}

const TABLE = 'sensor';                       // your table name
const START = new Date('2026-01-01T00:00:00Z'); // inclusive
const END   = new Date('2026-11-01T00:00:00Z'); // exclusive
const WINDOW_MS = 60 * 60 * 1000;             // 1 hour per page; tune to your data density

const client = new InfluxDBClient({
  host: INFLUXDB_HOST,
  token: INFLUXDB_TOKEN,
  database: INFLUXDB_DATABASE,
});

// Stop early if the database or table is missing. Queries never auto-create a
// database, so a typo in the name shows up here as an error or zero rows.
async function checkTarget() {
  try {
    let found = false;
    for await (const _ of client.query(
      `SELECT table_name FROM information_schema.tables WHERE table_name = $t LIMIT 1`,
      INFLUXDB_DATABASE,
      { type: 'sql', params: { t: TABLE } },
    )) found = true;
    if (!found) throw new Error(`Table "${TABLE}" not found in database "${INFLUXDB_DATABASE}"`);
  } catch (err) {
    console.error(`Startup check failed (status ${err.statusCode ?? 'n/a'}): ${err.message}`);
    process.exit(1);
  }
}

// Yields every row in [start, end), one window at a time.
async function* pageByTime(start, end, windowMs) {
  for (let t = start.getTime(); t < end.getTime(); t += windowMs) {
    const wStart = new Date(t).toISOString();
    const wEnd = new Date(Math.min(t + windowMs, end.getTime())).toISOString();

    const rows = client.query(
      `SELECT * FROM ${TABLE}
       WHERE time >= to_timestamp($start) AND time < to_timestamp($end)
       ORDER BY time`,
      INFLUXDB_DATABASE,
      { type: 'sql', params: { start: wStart, end: wEnd } },
    );

    let count = 0;
    for await (const row of rows) { count++; yield row; }
    console.error(`window ${wStart} -> ${wEnd}: ${count} rows`);
  }
}

async function main() {
  await checkTarget();
  let total = 0;
  try {
    for await (const row of pageByTime(START, END, WINDOW_MS)) {
      total++;
      // process(row) — write to file, transform, forward, etc.
    }
  } finally {
    await client.close();
  }
  console.error(`Done: ${total} rows`);
}

main().catch((err) => {
  console.error(`Query failed (status ${err.statusCode ?? 'n/a'}): ${err.message}`);
  process.exit(1);
});
