// would point you at an empty database. Check that the name exists first.
async function assertDatabaseExists() {
  const res = await fetch(`${INFLUXDB_HOST}/api/v3/configure/database?format=json`, {
    headers: { Authorization: `Bearer ${INFLUXDB_TOKEN}` },
  });
  if (!res.ok) throw new Error(`Listing databases failed: HTTP ${res.status} ${await res.text()}`);
  const dbs = (await res.json()).map((d) => d['iox::database']);
  if (!dbs.includes(INFLUXDB_DATABASE)) {
    throw new Error(`Database "${INFLUXDB_DATABASE}" not found. Existing: ${dbs.join(', ')}`);
  }
}

const client = new InfluxDBClient({
  host: INFLUXDB_HOST,
  token: INFLUXDB_TOKEN,
  database: INFLUXDB_DATABASE,
});

// Find the time range once. Epoch seconds avoid timestamp-type parsing on the client.
async function getTimeRange() {
  const sql = `SELECT date_part('epoch', MIN(time)) AS min_s,
                      date_part('epoch', MAX(time)) AS max_s
               FROM ${TABLE}`;
  for await (const row of client.query(sql, INFLUXDB_DATABASE, { type: 'sql' })) {
    if (row.min_s == null) return null; // empty table
    return {
      start: Math.floor(Number(row.min_s)) * 1000,
      end: (Math.floor(Number(row.max_s)) + 1) * 1000, // exclusive upper bound
    };
  }
  return null;
}

// Stream one window [startMs, endMs). Rows arrive in Arrow batches, not all at once.
async function* queryWindow(startMs, endMs) {
  const sql = `SELECT * FROM ${TABLE}
               WHERE time >= to_timestamp($start) AND time < to_timestamp($end)
               ORDER BY time`;
  const params = {
    start: new Date(startMs).toISOString(),
    end: new Date(endMs).toISOString(),
  };
  yield* client.query(sql, INFLUXDB_DATABASE, { type: 'sql', params });
}

// Retry a whole window on transient failures (429/5xx/network). Windows are
// idempotent, so re-running one is safe. Deduplicate in your sink if it can't tolerate
// a partially processed window being replayed.
async function processWindow(startMs, endMs, handleRow) {
  for (let attempt = 0; ; attempt++) {
    let count = 0;
    try {
      for await (const row of queryWindow(startMs, endMs)) {
        await handleRow(row);
        count++;
      }
      return count;
    } catch (err) {
      const status = err.statusCode;
      const transient = status === undefined || status === 429 || status >= 500;
      if (!transient || attempt >= MAX_RETRIES) throw err;
      const delay = Math.min(30_000, 500 * 2 ** attempt) * (0.5 + Math.random());
      console.warn(`Window ${new Date(startMs).toISOString()} failed (${status ?? 'network'}) ` +
                   `after ${count} rows; retrying in ${Math.round(delay)} ms`);
      await new Promise((r) => setTimeout(r, delay));
    }
  }
}

async function main() {
  await assertDatabaseExists();

  const range = await getTimeRange();
  if (!range) { console.log('No data.'); return; }

  // To resume after a crash, set range.start to the last completed window's end.
  let total = 0;
  for (let t = range.start; t < range.end; t += WINDOW_MS) {
    const end = Math.min(t + WINDOW_MS, range.end);
    const n = await processWindow(t, end, async (row) => {
      // TODO: your per-row work (write to file, transform, forward, etc.)
    });
    total += n;
    console.log(`${new Date(t).toISOString()} → ${new Date(end).toISOString()}: ${n} rows (total ${total})`);
  }
}

try {
  await main();
} finally {
  await client.close();
}
```

## Notes

- **Window size:** choose it so one window holds a manageable number of rows. 10M rows over 30 days is about 14k rows/hour, so 1-hour windows work well. Because rows stream, a big window costs time rather than memory. Still, smaller windows mean less work to redo when a retry happens.
- **Fewer columns:** if you only need some columns, list them instead of using `SELECT *`. If you only need one sensor, add a filter like `AND sensor_id = $sensor` and pass the value as a parameter, never by building it into the SQL string.
- **Parallel windows:** you can run 2–4 windows at once to speed things up. Recent InfluxDB 3 releases cap how many queries run at the same time and make extra ones wait, so heavy parallelism won't help. Keep a client timeout set.
- **If you really need numbered pages** (say, "page 37" in a UI), use `ORDER BY time LIMIT 1000 OFFSET n`. It works, but deep pages get slow on 10M rows. For a full export like this one, use time windows.
- **Not tested:** I haven't run this against your server. If `getTimeRange` returns timestamps you don't expect, check that `TABLE` matches your actual table name.

Use a **`PreparedStatement`** with `?` placeholders, and bind the user input with the `setXxx` methods. Never build the SQL by concatenating strings.

```java
String sql = "SELECT id, name, email FROM users WHERE email = ? AND status = ?";

try (Connection conn = dataSource.getConnection();
     PreparedStatement ps = conn.prepareStatement(sql)) {

    ps.setString(1, userEmail);   // indexes start at 1
    ps.setString(2, "active");

    try (ResultSet rs = ps.executeQuery()) {
        while (rs.next()) {
            long id = rs.getLong("id");
            String name = rs.getString("name");
            // ...
        }
    }
}
```

The driver sends the values separately from the SQL text, so input like `' OR '1'='1` is treated as a literal string and never runs as SQL.

### Common cases

**Use the typed setters:**
```java
ps.setInt(1, age);
ps.setLong(2, userId);
ps.setTimestamp(3, Timestamp.from(instant));   // or ps.setObject(3, localDateTime)
ps.setNull(4, Types.VARCHAR);
```

**LIKE searches:** put the wildcards in the value, not in the SQL. Escape `%` and `_` in the input if users shouldn't be able to use them as wildcards:
```java
String sql = "SELECT * FROM products WHERE name LIKE ? ESCAPE '\\'";
String escaped = input.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_");
ps.setString(1, "%" + escaped + "%");
```

**IN lists:** generate one `?` per value:
```java
String placeholders = String.join(",", Collections.nCopies(ids.size(), "?"));
String sql = "SELECT * FROM orders WHERE id IN (" + placeholders + ")";
try (PreparedStatement ps = conn.prepareStatement(sql)) {
    for (int i = 0; i < ids.size(); i++) ps.setLong(i + 1, ids.get(i));
    ...
}
```

**Identifiers (table names, column names, ORDER BY direction) can't be parameterized.** Check them against an allowlist you control:
```java
Map<String, String> sortable = Map.of("name", "name", "created", "created_at");
String col = sortable.getOrDefault(userSort, "created_at");
String dir = "desc".equalsIgnoreCase(userDir) ? "DESC" : "ASC";
String sql = "SELECT * FROM users ORDER BY " + col + " " + dir;
```

### If you use a framework
- **Spring `JdbcTemplate`:** `jdbcTemplate.query("... WHERE email = ?", mapper, email)`, or `NamedParameterJdbcTemplate` with `:email`.
- **JPA/Hibernate:** `em.createQuery("FROM User u WHERE u.email = :email", User.class).setParameter("email", email)`. Concatenating strings inside JPQL/HQL is just as injectable as raw SQL.
- **MyBatis:** use `#{param}`, which is safe. `${param}` does raw string substitution and is unsafe.

