A 429 means "Too Many Requests." The server is rate-limiting you, and the request is usually safe to retry after a delay. In Go, the standard fix is: read `Retry-After` if the server sent it, otherwise back off exponentially with jitter, and give up after a set number of attempts.

```go
package main

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"math/rand"
	"net/http"
	"strconv"
	"time"
)

func writeBatchWithRetry(ctx context.Context, c *http.Client, url string, body []byte, hdr http.Header) error {
	const maxAttempts = 6
	base, maxDelay := 500*time.Millisecond, 30*time.Second

	for attempt := 0; attempt < maxAttempts; attempt++ {
		req, err := http.NewRequestWithContext(ctx, http.MethodPost, url, bytes.NewReader(body)) // fresh body each try
		if err != nil {
			return err
		}
		req.Header = hdr.Clone()

		resp, err := c.Do(req)
		if err != nil {
			return err // or treat network errors as retryable too
		}
		io.Copy(io.Discard, resp.Body)
		resp.Body.Close()

		switch {
		case resp.StatusCode < 300:
			return nil
		case resp.StatusCode != http.StatusTooManyRequests && resp.StatusCode != http.StatusServiceUnavailable:
			return fmt.Errorf("write failed: %s", resp.Status) // 4xx like 400/401: don't retry
		}

		// Prefer the server's hint.
		delay := retryAfter(resp.Header.Get("Retry-After"))
		if delay == 0 {
			d := base << attempt
			if d > maxDelay {
				d = maxDelay
			}
			delay = time.Duration(rand.Int63n(int64(d))) // full jitter
		}

		select {
		case <-time.After(delay):
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	return fmt.Errorf("write failed: still rate-limited after %d attempts", maxAttempts)
}

func retryAfter(v string) time.Duration {
	if v == "" {
		return 0
	}
	if s, err := strconv.Atoi(v); err == nil {
		return time.Duration(s) * time.Second
	}
	if t, err := http.ParseTime(v); err == nil {
		return time.Until(t)
	}
	return 0
}
```

**Key points:**
- **Create a new request body for every attempt.** A `bytes.Reader` that was already sent is empty, so reusing it sends nothing.
- **Use jitter.** If many workers retry at the same moment, they'll all hit the limit again.
- **Send less at once if 429s keep happening.** Use fewer goroutines writing at the same time (a buffered-channel semaphore or `golang.org/x/time/rate` works), smaller batches, or a longer flush interval. Retrying only covers short bursts.
- **Check whether part of the batch was accepted.** Some APIs accept part of a batch and tell you which items failed. Retry only those items so you don't write duplicates.
- **Read the response body before discarding it.** It often says which limit you hit, such as requests per second, bytes, or a plan quota.

